 $pattern='bool '+$Actual+' = (?<expression>[^;]+);\s*AICF_Observe(?:TerminalAdmission|CapturedCleanup)Decision\([^;]+;\s*return '+$Actual+';'
 return [regex]::Replace($b,$pattern,'return ${expression};')
}
